#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {
TOTAL_STAGES=4
umask 077
[[ "${EUID}" -eq 0 ]] || { say "Run this reviewed helper as the installation administrator with sudo."; return 1; }
[[ -t 0 ]] || { say "An interactive terminal is required; never put the owner's password in a command."; return 1; }
[[ "${SHELLOPTS}" != *xtrace* ]] || { say "Disable shell tracing before entering credentials."; return 1; }
cd "$(dirname "${BASH_SOURCE[0]}")/../.."
trap 'unset OWNER_PASSWORD OWNER_PASSWORD_CONFIRM' EXIT
banner "Enroll the existing HR owner"

stage "Installation configuration"
say "This enrolls an exact existing HR administrator. It does not activate authentication or change routing."
say "Choose the private deployment environment file containing the migration connection."
ask AIHR_DEPLOY_ENV "Absolute deployment env path (for example /etc/aihr/deploy.env):"
[[ "$AIHR_DEPLOY_ENV" = /* && -f "$AIHR_DEPLOY_ENV" && ! -L "$AIHR_DEPLOY_ENV" ]] || { say "Use a regular absolute file, not a symlink."; return 1; }
ENV_FILE="$AIHR_DEPLOY_ENV"
# Deployment environment files contain privileged credentials. Refuse mutable/untrusted shell input.
[[ "$(stat -c %u "$ENV_FILE")" = 0 && "$(stat -c %a "$ENV_FILE")" = 600 ]] || {
  say "The deployment env file must be root-owned, mode 0600. Ask the installation administrator to secure it first."; return 1;
}
ask AIHR_NODE "Supported Node executable (for example /opt/node24/bin/node):"
[[ "$AIHR_NODE" = /* && -x "$AIHR_NODE" ]] || { say "Use an absolute installed Node executable."; return 1; }
"$AIHR_NODE" -e 'const [a,b]=process.versions.node.split(".").map(Number);if(!(a===24||a===22&&b>=13))process.exit(1)' || {
  say "Install Node.js 22.13+ or 24 LTS before enrollment."; return 1;
}
[[ -f db/migrations/0543_embedded_authentication.sql && -f node_modules/tsx/dist/loader.mjs ]] || {
  say "Deploy the verified embedded-authentication release first."; return 1;
}
backup="${ENV_FILE}.before-internal-$(date -u +%Y%m%dT%H%M%SZ)-$$"
[[ ! -e "$backup" ]] || return 1
cp -p "$ENV_FILE" "$backup"
say "A private environment backup has been created beside the original."

stage "HTTPS origin and encryption key"
ask AUTH_PUBLIC_ORIGIN "Canonical HTTPS HR origin, without a path:"
"$AIHR_NODE" -e 'const u=new URL(process.argv[1]);if(u.protocol!=="https:"||u.username||u.password||u.pathname!=="/"||u.search||u.hash)process.exit(1)' "$AUTH_PUBLIC_ORIGIN"
write_env AUTH_PUBLIC_ORIGIN "$AUTH_PUBLIC_ORIGIN"
AUTH_SESSION_KEY="$(_existing AUTH_SESSION_KEY || true)"
if [[ ! "$AUTH_SESSION_KEY" =~ ^[a-fA-F0-9]{64}$ ]]; then
  [[ -z "$AUTH_SESSION_KEY" ]] || { say "An existing invalid key requires operator review; it will not be overwritten."; return 1; }
  AUTH_SESSION_KEY="$(openssl rand -hex 32)"
  write_env AUTH_SESSION_KEY "$AUTH_SESSION_KEY"
fi
say "Back up this encryption key together with the database; losing it prevents credential and MFA recovery."
say "For customer deployments, copy AUTH_PUBLIC_ORIGIN and AUTH_SESSION_KEY to the private runtime env through your deployment operator."
say "Never copy the migration connection into the web service's runtime environment."
pause "Press Enter after arranging the private key backup."

stage "Enroll the exact HR administrator"
say "Find the active group administrator's UUID in your existing HR records. Do not choose by email alone."
ask OWNER_APP_USER_ID "Existing administrator app_user UUID:"
ask OWNER_ORGANIZATION "Organization login code (lowercase letters, digits, hyphens):"
ask OWNER_USERNAME "Owner username:"
ask OWNER_EMAIL "Verified owner email:"
ask_secret OWNER_PASSWORD "Temporary owner password (at least 14 characters):"
ask_secret OWNER_PASSWORD_CONFIRM "Repeat temporary password:"
[[ "$OWNER_PASSWORD" = "$OWNER_PASSWORD_CONFIRM" ]] || { say "Passwords differ. Nothing was enrolled."; return 1; }
owner_option=()
if confirm "Is this the installation operator who may configure the installation SMTP relay?"; then owner_option=(--installation-owner); fi
confirm "Enroll these credentials on the exact existing HR administrator, preserving all grants?" || return 1
set -a
# The root-owned deployment environment is already the installation operator's trusted shell input.
. "$ENV_FILE"
set +a
printf '%s' "$OWNER_PASSWORD" | AUTH_PROVIDER=internal "$AIHR_NODE" --import tsx scripts/internal-auth-bootstrap.ts \
  "--app-user-id=$OWNER_APP_USER_ID" "--organization=$OWNER_ORGANIZATION" "--username=$OWNER_USERNAME" \
  "--email=$OWNER_EMAIL" --password-stdin "${owner_option[@]}"
unset OWNER_PASSWORD OWNER_PASSWORD_CONFIRM

stage "Activation prerequisites"
say "Enrollment is prepared. The current authentication provider has not been changed."
say "Before cutover, verify the origin certificate, proxy trust settings, HTTPS hostname and expiry."
say "Then use the reviewed deployment procedure to set AUTH_PROVIDER=internal and ALLOW_DEMO_SESSION=false, validate customer preflight, and restart the built app."
say "Open $AUTH_PUBLIC_ORIGIN/login. The owner changes the temporary password, enrolls an authenticator and saves the one-time recovery codes privately."
say "Configure and verify SMTP from Admin → Email delivery after sign-in."
say "No Keycloak activation, proxy change, mail replay or service removal was performed."
finish
}

run_wizard "$@"; exit
